import {createSurface} from './surface.js';
const p=(key,label,min,max,value)=>({key,label,min,max,value,step:1});
export const MOTION_EFFECTS={particleflow:{name:'粒子流场',cat:'实验',icon:'✺',params:[p('amount','亮度',0,100,65),p('count','粒子数量',10,400,140),p('speed','循环圈数',0,5,1),p('seed','随机种子',1,999,17)]},liquidfield:{name:'液态流场',cat:'实验',icon:'≈',params:[p('amount','位移',0,100,35),p('frequency','流场密度',1,12,4),p('speed','循环圈数',0,5,1)]},tileorbit:{name:'分片重组',cat:'实验',icon:'▧',params:[p('amount','散开幅度',0,100,50),p('size','分片数量',3,20,9),p('speed','循环圈数',0,5,1)]}};
for(const [key,name,icon,count] of [['embers','余烬与萤火','✦',80],['confetti','纸屑礼花','▱',90],['rainfall','雨幕玻璃','╱',160],['bokehdrift','景深光斑','◌',35]])MOTION_EFFECTS[key]={name,cat:'实验',icon,params:[p('amount','强度',0,100,55),p('count','数量',10,300,count),p('speed','循环圈数',1,4,1),p('seed','随机种子',1,999,23)]};
for(const spec of Object.values(MOTION_EFFECTS))spec.desc=spec.desc||'可循环的图层动态效果 · 支持数量、速度与强度调整';
const random=(i,s)=>{const n=Math.sin(i*127.1+s*311.7)*43758.5453;return n-Math.floor(n)};
export function applyMotionFx(c,e,t=0,duration=5){const x=c.getContext('2d'),w=c.width,h=c.height,p=e.params,phase=Math.PI*2*t/Math.max(.01,duration)*p.speed,m=p.amount/100;if(!m)return c;let z;if(e.type==='tileorbit'){z=createSurface(w,h);z.getContext('2d').drawImage(c,0,0);}
 if(['embers','confetti','rainfall','bokehdrift'].includes(e.type)){const cycle=((t/Math.max(.01,duration)*p.speed)%1+1)%1;x.save();x.globalCompositeOperation='source-atop';for(let i=0;i<p.count;i++){const u=random(i,p.seed),v=random(i+917,p.seed),depth=.2+random(i+173,p.seed)*.8,a=cycle*Math.PI*2;const px=(u+Math.sin(a+v*12)*.04*depth)*w,py=((v+cycle)%1)*h;if(e.type==='embers'){const yy=((v-cycle+2)%1)*h,r=(.7+depth*2.8)*Math.max(.5,w/700);x.globalAlpha=m*(.25+.75*(.5+.5*Math.sin(a*2+u*18)));const g=x.createRadialGradient(px,yy,0,px,yy,r*5);g.addColorStop(0,'#fff7c7');g.addColorStop(.18,'#ffbb66');g.addColorStop(1,'#ff663300');x.fillStyle=g;x.fillRect(px-r*5,yy-r*5,r*10,r*10);}if(e.type==='confetti'){x.save();x.translate(px,py);x.rotate(a*(1+i%3)+v*6);x.globalAlpha=m*(.5+depth*.5);x.fillStyle=['#e2ab9d','#e6d09c','#99c9c9','#b1a3d4'][i%4];const r=(2+depth*5)*w/700;x.scale(Math.max(.08,Math.abs(Math.cos(a+u*6))),1);x.fillRect(-r,-r*.4,r*2,r*.8);x.restore();}if(e.type==='rainfall'){const len=(.015+depth*.05)*h;x.globalAlpha=m*(.15+depth*.4);x.strokeStyle='#cadce6';x.lineWidth=Math.max(.6,depth*w/700*1.5);x.beginPath();x.moveTo(px,py);x.lineTo(px-len*.28,py+len);x.stroke();}if(e.type==='bokehdrift'){const yy=(v+Math.cos(a+u*12)*.06)*h,r=(.008+depth*.035)*w;x.globalAlpha=m*(.15+.25*(.5+.5*Math.sin(a+u*8)));const g=x.createRadialGradient(px,yy,0,px,yy,r);g.addColorStop(0,i%2?'#ffe6baaa':'#badfeaaa');g.addColorStop(.65,i%2?'#ffe6ba55':'#badfea55');g.addColorStop(1,'#ffffff00');x.fillStyle=g;x.fillRect(px-r,yy-r,r*2,r*2);}}x.restore();}
 if(e.type==='particleflow'){x.save();x.globalCompositeOperation='source-atop';for(let i=0;i<p.count;i++){const u=random(i,p.seed),v=random(i+700,p.seed),a=phase+u*6.28,r=(.03+v*.13),px=(u+Math.sin(a+v*9)*r)*w,py=(v+Math.cos(a*1+u*12)*r)*h;x.strokeStyle=`rgba(210,235,255,${m*(.15+v*.65)})`;x.lineWidth=Math.max(.6,w/700);x.beginPath();for(let k=0;k<9;k++){const q=a-k*.025,sx=(u+Math.sin(q+v*9)*r)*w,sy=(v+Math.cos(q+u*12)*r)*h;k?x.lineTo(sx,sy):x.moveTo(sx,sy)}x.stroke();x.fillStyle=`rgba(255,235,180,${m})`;x.beginPath();x.arc(px,py,Math.max(.7,w/700)*(1+v),0,6.29);x.fill()}x.restore();}
 if(e.type==='liquidfield'){const im=x.getImageData(0,0,w,h),src=new Uint8ClampedArray(im.data),a=im.data;for(let y=0;y<h;y++)for(let xx=0;xx<w;xx++){const sx=Math.max(0,Math.min(w-1,Math.round(xx+Math.sin(y/h*p.frequency*6.28+phase+Math.sin(xx/w*6.28-phase))*w*.04*m))),sy=Math.max(0,Math.min(h-1,Math.round(y+Math.cos(xx/w*p.frequency*6.28-phase)*h*.03*m))),i=(y*w+xx)*4,j=(sy*w+sx)*4;for(let k=0;k<4;k++)a[i+k]=src[j+k]}x.putImageData(im,0,0);}
 if(e.type==='tileorbit'){x.clearRect(0,0,w,h);const n=p.size,sw=w/n,sh=h/n,spread=(1-Math.cos(phase))*.5*m;for(let j=0;j<n;j++)for(let i=0;i<n;i++){const dx=(i-(n-1)/2)*sw*.3*spread,dy=(j-(n-1)/2)*sh*.3*spread;x.save();x.translate((i+.5)*sw+dx,(j+.5)*sh+dy);x.rotate(Math.sin(phase+(i+j)*.3)*spread*.18);x.drawImage(z,i*sw,j*sh,sw,sh,-sw/2,-sh/2,sw+.5,sh+.5);x.restore();}}return c;}
